    # Fill short gaps between marked cells, repeatedly so newly completed
    # segments can join up with perpendicular segments.
    changed = True
    while changed:
        changed = False
        for coords in (
            [[(r, c) for c in range(w)] for r in range(h)] +
            [[(r, c) for r in range(h)] for c in range(w)]
        ):
            pos = [i for i, (r, c) in enumerate(coords) if out[r][c] in (mark, 2)]
